INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000205,'challenges','{"id":760300000000205,"title":"C1 · Политика · Общество и правила · Challenge 5","description":"C1: общество и правила. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"⚡","xp":46,"category":"Общество и правила","track":"Политика","topic":"Общество и правила","duration":"11 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «parliamentary scrutiny».","options":["парламентский контроль","обсуждение на основе фактических данных","подотчётность государственного сектора","гражданская вовлечённость"],"correctAnswer":"парламентский контроль","explanation":"«parliamentary scrutiny» — «парламентский контроль»."},{"id":2,"question":"Какое выражение на британском английском соответствует «подотчётность государственного сектора»?","options":["procedural fairness","conflict of interest","institutional safeguards","public-sector accountability"],"correctAnswer":"public-sector accountability","explanation":"«public-sector accountability» — «подотчётность государственного сектора»."},{"id":3,"question":"Выбери точное русское значение выражения «evidence-based deliberation».","options":["обсуждение на основе фактических данных","толкование конституции","демократическая легитимность","оценка государственной политики"],"correctAnswer":"обсуждение на основе фактических данных","explanation":"«evidence-based deliberation» — «обсуждение на основе фактических данных»."},{"id":4,"question":"Выбери точное русское значение выражения «conflict of interest».","options":["парламентский контроль","институциональные гарантии","гражданская вовлечённость","конфликт интересов"],"correctAnswer":"конфликт интересов","explanation":"«conflict of interest» — «конфликт интересов»."},{"id":5,"question":"Какое выражение на британском английском соответствует «независимость судебной власти»?","options":["conflict of interest","judicial independence","public-sector accountability","deliberative democracy"],"correctAnswer":"judicial independence","explanation":"«judicial independence» — «независимость судебной власти»."},{"id":6,"question":"Выбери точное русское значение выражения «constitutional interpretation».","options":["конфликт интересов","процедурная справедливость","обсуждение на основе фактических данных","толкование конституции"],"correctAnswer":"толкование конституции","explanation":"«constitutional interpretation» — «толкование конституции»."},{"id":7,"question":"Выбери точное русское значение выражения «procedural fairness».","options":["независимость судебной власти","подотчётность государственного сектора","институциональные гарантии","процедурная справедливость"],"correctAnswer":"процедурная справедливость","explanation":"«procedural fairness» — «процедурная справедливость»."},{"id":8,"question":"Какое выражение на британском английском соответствует «гражданская вовлечённость»?","options":["parliamentary scrutiny","civic engagement","constitutional interpretation","conflict of interest"],"correctAnswer":"civic engagement","explanation":"«civic engagement» — «гражданская вовлечённость»."}],"durationMinutes":11,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 46 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000206,'challenges','{"id":760300000000206,"title":"C2 · Политика · Общество и правила · Challenge 6","description":"C2: общество и правила. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"⚡","xp":54,"category":"Общество и правила","track":"Политика","topic":"Общество и правила","duration":"12 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «avoid partisan framing».","options":["оспорить неподкреплённое утверждение","оценить устойчивость демократии","отличить корреляцию от причинности","избегать партийно-пристрастной подачи"],"correctAnswer":"избегать партийно-пристрастной подачи","explanation":"«avoid partisan framing» — «избегать партийно-пристрастной подачи»."},{"id":2,"question":"Какое выражение на британском английском соответствует «обеспечить беспристрастность суда»?","options":["assess democratic resilience","scrutinise constitutional constraints","safeguard judicial impartiality","reconcile competing public interests"],"correctAnswer":"safeguard judicial impartiality","explanation":"«safeguard judicial impartiality» — «обеспечить беспристрастность суда»."},{"id":3,"question":"Выбери точное русское значение выражения «analyse regulatory capture».","options":["оспорить неподкреплённое утверждение","изучить процессуальные гарантии","сформулировать проверку соразмерности","проанализировать захват регулятора"],"correctAnswer":"проанализировать захват регулятора","explanation":"«analyse regulatory capture» — «проанализировать захват регулятора»."},{"id":4,"question":"Выбери точное русское значение выражения «reconcile competing public interests».","options":["оспорить неподкреплённое утверждение","сформулировать проверку соразмерности","согласовать конкурирующие общественные интересы","обеспечить беспристрастность суда"],"correctAnswer":"согласовать конкурирующие общественные интересы","explanation":"«reconcile competing public interests» — «согласовать конкурирующие общественные интересы»."},{"id":5,"question":"Какое выражение на британском английском соответствует «тщательно изучить конституционные ограничения»?","options":["scrutinise constitutional constraints","reconcile competing public interests","evaluate institutional legitimacy","articulate a proportionality test"],"correctAnswer":"scrutinise constitutional constraints","explanation":"«scrutinise constitutional constraints» — «тщательно изучить конституционные ограничения»."},{"id":6,"question":"Выбери точное русское значение выражения «assess democratic resilience».","options":["оценить устойчивость демократии","отличить корреляцию от причинности","сбалансировать прозрачность и конфиденциальность","сформулировать проверку соразмерности"],"correctAnswer":"оценить устойчивость демократии","explanation":"«assess democratic resilience» — «оценить устойчивость демократии»."},{"id":7,"question":"Выбери точное русское значение выражения «challenge an unsubstantiated claim».","options":["сформулировать проверку соразмерности","оценить устойчивость демократии","проанализировать захват регулятора","оспорить неподкреплённое утверждение"],"correctAnswer":"оспорить неподкреплённое утверждение","explanation":"«challenge an unsubstantiated claim» — «оспорить неподкреплённое утверждение»."},{"id":8,"question":"Какое выражение на британском английском соответствует «оценить легитимность института»?","options":["examine procedural safeguards","challenge an unsubstantiated claim","evaluate institutional legitimacy","balance transparency and privacy"],"correctAnswer":"evaluate institutional legitimacy","explanation":"«evaluate institutional legitimacy» — «оценить легитимность института»."}],"durationMinutes":12,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 54 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
