INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000208,'challenges','{"id":760300000000208,"title":"A2 · Политика · Гражданская жизнь · Challenge 8","description":"A2: гражданская жизнь. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"⚡","xp":31,"category":"Гражданская жизнь","track":"Политика","topic":"Гражданская жизнь","duration":"8 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «make a decision».","options":["соблюдать правило","поделиться мнением","общественная библиотека","принять решение"],"correctAnswer":"принять решение","explanation":"«make a decision» — «принять решение»."},{"id":2,"question":"Какое выражение на британском английском соответствует «соблюдать правило»?","options":["public discussion","elect a leader","public service","follow a rule"],"correctAnswer":"follow a rule","explanation":"«follow a rule» — «соблюдать правило»."},{"id":3,"question":"Выбери точное русское значение выражения «public library».","options":["общественная дискуссия","общественная библиотека","собрание сообщества","поделиться мнением"],"correctAnswer":"общественная библиотека","explanation":"«public library» — «общественная библиотека»."},{"id":4,"question":"Выбери точное русское значение выражения «public service».","options":["местный совет","школьный совет","государственная услуга","принять решение"],"correctAnswer":"государственная услуга","explanation":"«public service» — «государственная услуга»."},{"id":5,"question":"Какое выражение на британском английском соответствует «школьный совет»?","options":["public service","school council","share an opinion","equal treatment"],"correctAnswer":"school council","explanation":"«school council» — «школьный совет»."},{"id":6,"question":"Выбери точное русское значение выражения «citizens'' rights».","options":["общественная дискуссия","поделиться мнением","школьный совет","права граждан"],"correctAnswer":"права граждан","explanation":"«citizens'' rights» — «права граждан»."},{"id":7,"question":"Выбери точное русское значение выражения «equal treatment».","options":["избрать лидера","собрание сообщества","соблюдать правило","равное обращение"],"correctAnswer":"равное обращение","explanation":"«equal treatment» — «равное обращение»."},{"id":8,"question":"Какое выражение на британском английском соответствует «избрать лидера»?","options":["make a decision","elect a leader","local council","follow a rule"],"correctAnswer":"elect a leader","explanation":"«elect a leader» — «избрать лидера»."}],"durationMinutes":8,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 31 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000209,'challenges','{"id":760300000000209,"title":"B1 · Политика · Гражданская жизнь · Challenge 9","description":"B1: гражданская жизнь. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"⚡","xp":36,"category":"Гражданская жизнь","track":"Политика","topic":"Гражданская жизнь","duration":"9 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «representative democracy».","options":["мирное выражение несогласия","государственная политика","общественный интерес","представительная демократия"],"correctAnswer":"представительная демократия","explanation":"«representative democracy» — «представительная демократия»."},{"id":2,"question":"Какое выражение на британском английском соответствует «мирное выражение несогласия»?","options":["civic participation","peaceful disagreement","local election","public interest"],"correctAnswer":"peaceful disagreement","explanation":"«peaceful disagreement» — «мирное выражение несогласия»."},{"id":3,"question":"Выбери точное русское значение выражения «independent journalism».","options":["гражданское участие","общественный интерес","общественная ответственность","независимая журналистика"],"correctAnswer":"независимая журналистика","explanation":"«independent journalism» — «независимая журналистика»."},{"id":4,"question":"Выбери точное русское значение выражения «local election».","options":["представительная демократия","система голосования","местные выборы","общественная ответственность"],"correctAnswer":"местные выборы","explanation":"«local election» — «местные выборы»."},{"id":5,"question":"Какое выражение на британском английском соответствует «государственная политика»?","options":["public policy","local election","peaceful disagreement","public interest"],"correctAnswer":"public policy","explanation":"«public policy» — «государственная политика»."},{"id":6,"question":"Выбери точное русское значение выражения «public interest».","options":["независимая журналистика","система голосования","государственная политика","общественный интерес"],"correctAnswer":"общественный интерес","explanation":"«public interest» — «общественный интерес»."},{"id":7,"question":"Выбери точное русское значение выражения «reliable source».","options":["государственная политика","система голосования","мирное выражение несогласия","надёжный источник"],"correctAnswer":"надёжный источник","explanation":"«reliable source» — «надёжный источник»."},{"id":8,"question":"Какое выражение на британском английском соответствует «общественная ответственность»?","options":["social responsibility","local election","civic participation","voting system"],"correctAnswer":"social responsibility","explanation":"«social responsibility» — «общественная ответственность»."}],"durationMinutes":9,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 36 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
