ра","школьный совет","принять решение"],"correctAnswer":"школьный совет","explanation":"«school council» — «школьный совет»."},{"id":7,"question":"Выбери точное русское значение выражения «equal treatment».","options":["поделиться мнением","соблюдать правило","избрать лидера","равное обращение"],"correctAnswer":"равное обращение","explanation":"«equal treatment» — «равное обращение»."},{"id":8,"question":"Какое выражение на британском английском соответствует «права граждан»?","options":["share an opinion","follow a rule","citizens'' rights","make a decision"],"correctAnswer":"citizens'' rights","explanation":"«citizens'' rights» — «права граждан»."}],"durationMinutes":8,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 31 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000215,'challenges','{"id":760300000000215,"title":"B1 · Политика · Общественные обсуждения · Challenge 15","description":"B1: общественные обсуждения. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"⚡","xp":36,"category":"Общественные обсуждения","track":"Политика","topic":"Общественные обсуждения","duration":"9 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «reliable source».","options":["надёжный источник","общественный интерес","государственное финансирование","мирное выражение несогласия"],"correctAnswer":"надёжный источник","explanation":"«reliable source» — «надёжный источник»."},{"id":2,"question":"Какое выражение на британском английском соответствует «местные выборы»?","options":["local election","reliable source","voting system","social responsibility"],"correctAnswer":"local election","explanation":"«local election» — «местные выборы»."},{"id":3,"question":"Выбери точное русское значение выражения «public policy».","options":["независимая журналистика","государственная политика","общественные дебаты","мирное выражение несогласия"],"correctAnswer":"государственная политика","explanation":"«public policy» — «государственная политика»."},{"id":4,"question":"Выбери точное русское значение выражения «peaceful disagreement».","options":["независимая журналистика","государственная политика","государственное финансирование","мирное выражение несогласия"],"correctAnswer":"мирное выражение несогласия","explanation":"«peaceful disagreement» — «мирное выражение несогласия»."},{"id":5,"question":"Какое выражение на британском английском соответствует «система голосования»?","options":["voting system","independent journalism","peaceful disagreement","social responsibility"],"correctAnswer":"voting system","explanation":"«voting system» — «система голосования»."},{"i