INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000216,'challenges','{"id":760300000000216,"title":"B2 · Политика · Общественные обсуждения · Challenge 16","description":"B2: общественные обсуждения. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"⚡","xp":44,"category":"Общественные обсуждения","track":"Политика","topic":"Общественные обсуждения","duration":"10 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «electoral participation».","options":["независимый надзор","прозрачность институтов","конституционные права","участие в выборах"],"correctAnswer":"участие в выборах","explanation":"«electoral participation» — «участие в выборах»."},{"id":2,"question":"Какое выражение на британском английском соответствует «реализация государственной политики»?","options":["political accountability","public consultation","electoral participation","policy implementation"],"correctAnswer":"policy implementation","explanation":"«policy implementation» — «реализация государственной политики»."},{"id":3,"question":"Выбери точное русское значение выражения «public consultation».","options":["прозрачность институтов","общественные консультации","независимый надзор","реализация государственной политики"],"correctAnswer":"общественные консультации","explanation":"«public consultation» — «общественные консультации»."},{"id":4,"question":"Выбери точное русское значение выражения «media literacy».","options":["медиаграмотность","прозрачность институтов","участие в выборах","независимый надзор"],"correctAnswer":"медиаграмотность","explanation":"«media literacy» — «медиаграмотность»."},{"id":5,"question":"Какое выражение на британском английском соответствует «независимый надзор»?","options":["legislative proposal","evidence-based policy","minority representation","independent oversight"],"correctAnswer":"independent oversight","explanati