INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000217,'challenges','{"id":760300000000217,"title":"C1 · Политика · Общественные обсуждения · Challenge 17","description":"C1: общественные обсуждения. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"⚡","xp":46,"category":"Общественные обсуждения","track":"Политика","topic":"Общественные обсуждения","duration":"11 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «constitutional interpretation».","options":["конфликт интересов","обсуждение на основе фактических данных","оценка государственной политики","толкование конституции"],"correctAnswer":"толкование конституции","explanation":"«constitutional interpretation» — «толкование конституции»."},{"id":2,"question":"Какое выражение на британском английском соответствует «процедурная справедливость»?","options":["procedural fairness","parliamentary scrutiny","public-sector accountability","conflict of interest"],"correctAnswer":"procedural fairness","explanation":"«procedural fairness» — «процедурная справедливость»."},{"id":3,"question":"Выбери точное русское значение выражения «judicial independence».","options":["процедурная справедливость","делиберативная демократия","независимость судебной власти","парламентский контроль"],"correctAnswer":"независимость судебной власти","explanation":"«judicial independence» — «независимость судебной власти»."},{"id":4,"question":"Выбери точное русское значение выражения «institutional safeguards».","options":["парламентский контроль","демократическая легитимность","институциональные гарантии","делиберативная демократия"],"correctAnswer":"институциональные гарантии","explanation":"«institutional safeguards» — «институциональные гарантии»."},{"id":5,"question":"Какое выражение на британском английском соответствует «оценка государственной политики»?","options":["procedural fairness",