INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000218,'challenges','{"id":760300000000218,"title":"C2 · Политика · Общественные обсуждения · Challenge 18","description":"C2: общественные обсуждения. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"⚡","xp":51,"category":"Общественные обсуждения","track":"Политика","topic":"Общественные обсуждения","duration":"12 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «safeguard judicial impartiality».","options":["оспорить неподкреплённое утверждение","сбалансировать прозрачность и конфиденциальность","сформулировать проверку соразмерности","обеспечить беспристрастность суда"],"correctAnswer":"обеспечить беспристрастность суда","explanation":"«safeguard judicial impartiality» — «обеспечить беспристрастность суда»."},{"id":2,"question":"Какое выражение на британском английском соответствует «согласовать конкурирующие общественные интересы»?","options":["assess democratic resilience","reconcile competing public interests","scrutinise constitutional constraints","examine procedural safeguards"],"correctAnswer":"reconcile competing public interests","explanation":"«reconcile competing public interests» — «согласовать конкурирующие общественные интересы»."},{"id":3,"question":"Выбери точное русское значение выражения «scrutinise constitutional constraints».","options":["тщательно изучить конституционные ограничения","согласовать конкурирующие общественные интересы","проанализировать захват регулятора","отличить корреляцию от причинности"],"correctAnswer":"тщательно изучить конституционные ограничения","explanation":"«scrutinise constitutional constraints» — «тщательно изучить конституционные ограничения»."},{"id":4,"question":"Выбери точное русское значение выражения «challenge an unsubstantiated claim».","options":["обеспечить беспристрастность суда","проанализировать захват регулятора","согласовать конкурирующие общественные интересы","оспорить неподкреплённое утверждение"],"correctAnswer":"оспорить неподкреплённое утверждение","explanation":"«challenge an unsubstantiated claim» — «оспорить неподкреплённое утверждение»."},{"id":5,"question":"Какое выражение на британском английском соответствует «изучить процессуальные гарантии»?","options":["avoid partisan framing","examine procedural safeguards","evaluate institutional legitimacy","analyse regulatory capture"],"correctAnswer":"examine procedural safeguards","explanation":"«examine procedural safeguards» — «изучить процессуальные гарантии»."},{"id":6,"question":"Выбери точное русское значение выражения «articulate a proportionality test».","options":["сбалансировать прозрачность и конфиденциальность","изучить процессуальные гарантии","проанализировать захват регулятора","сформулировать проверку соразмерности"],"correctAnswer":"сформулировать проверку соразмерности","explanation":"«articulate a proportionality test» — «сформулировать проверку соразмерности»."},{"id":7,"question":"Выбери точное русское значение выражения «balance transparency and privacy».","options":["сбалансировать прозрачность и конфиденциальность","отличить корреляцию от причинности","оспорить неподкреплённое утверждение","оценить устойчивость демократии"],"correctAnswer":"сбалансировать прозрачность и конфиденциальность","explanation":"«balance transparency and privacy» — «сбалансировать прозрачность и конфиденциальность»."},{"id":8,"question":"Какое выражение на британском английском соответствует «отличить корреляцию от причинности»?","options":["distinguish correlation from causation","safeguard judicial impartiality","assess democratic resilience","analyse regulatory capture"],"correctAnswer":"distinguish correlation from causation","explanation":"«distinguish correlation from causation» — «отличить корреляцию от причинности»."}],"durationMinutes":12,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 51 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
