ity","explanation":"«city» — «город»."}],"durationMinutes":7,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 26 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000220,'challenges','{"id":760300000000220,"title":"A2 · Политика · Институты и решения · Challenge 20","description":"A2: институты и решения. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"⚡","xp":31,"category":"Институты и решения","track":"Политика","topic":"Институты и решения","duration":"8 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «public discussion».","options":["равное обращение","местный совет","государственная услуга","общественная дискуссия"],"correctAnswer":"общественная дискуссия","explanation":"«public discussion» — «общественная дискуссия»."},{"id":2,"question":"Какое выражение на британском английском соответствует «принять решение»?","options":["public service","make a decision","elect a leader","follow a rule"],"correctAnswer":"make a decision","explanation":"«make a decision» — «принять решение»."},{"id":3,"question":"Выбери точное русское значение выражения «local council».","options":["местный совет","соблюдать правило","избрать лидера","равное обращение"],"correctAnswer":"местный совет","explanation":"«local council» — «местный совет»."},{"id":4,"question":"Выбери точное русское значение выражения «citizens'' rights».","options":["равное обращение","права граждан","избрать лидера","общественная библиотека"],"correctAnswer":"права граждан","explanation":"«citizens'' rights» — «права граждан»."},{"id":5,"question":"Какое выражение на британском английском соответствует «государственная услуга»?","options":["make a decision","public library","public service","share an opinion"],"correctAnswer":"public service","explanation":"«public service» — «государственная услуга»."},{"id":6,"question":"Выбери точное русское значение выражения «community meeting».","options":["местный совет","собрание сообщества","соблюдать правило","права граждан"],"