INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000221,'challenges','{"id":760300000000221,"title":"B1 · Политика · Институты и решения · Challenge 21","description":"B1: институты и решения. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"⚡","xp":39,"category":"Институты и решения","track":"Политика","topic":"Институты и решения","duration":"9 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «local election».","options":["местные выборы","мирное выражение несогласия","общественная ответственность","государственная политика"],"correctAnswer":"местные выборы","explanation":"«local election» — «местные выборы»."},{"id":2,"question":"Какое выражение на британском английском соответствует «государственная политика»?","options":["peaceful disagreement","civic participation","government funding","public policy"],"correctAnswer":"public policy","explanation":"«public policy» — «государственная политика»."},{"id":3,"question":"Выбери точное русское значение выражения «representative democracy».","options":["надёжный источник","представительная демократия","местные выборы","общественные дебаты"],"correctAnswer":"представительная демократия","explanation":"«representative democracy» — «представительная демократия»."},{"id":4,"question":"Выбери точное русское значение выражения «civic participation».","options":["общественные дебаты","гражданское участие","независимая журналистика","система голосования"],"correctAnswer":"гражданское участие","explanation":"«civic participation» — «гражданское участие»."},{"id":5,"question":"Какое выражение на британском английском соответствует «надёжный источник»?","options":["social responsibility","independent journalism","reliable source","voting system"],"correctAnswer":"reliable source","explanation":"«reliable source» — «надёжный источник»."},{"id":6,"question":"Выбери точное русское значение выражения «government funding».","options":["местные выборы","гражданское участие","государственное финансирование","независимая журналистика"],"correctAnswer":"государственное финансирование","explanation":"«government funding» — «государственное финансирование»."},{"id":7,"question":"Выбери точное русское значение выражения «social responsibility».","options":["система голосования","местные выборы","общественная ответственность","надёжный источник"],"correctAnswer":"общественная ответственность","explanation":"«social responsibility» — «общественная ответственность»."},{"id":8,"question":"Какое выражение на британском английском соответствует «общественные дебаты»?","options":["government funding","reliable source","public interest","public debate"],"correctAnswer":"public debate","explanation":"«public debate» — «общественные дебаты»."}],"durationMinutes":9,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 39 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000222,'challenges','{"id":760300000000222,"title":"B2 · Политика · Институты и решения · Challenge 22","description":"B2: институты и решения. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"⚡","xp":41,"category":"Институты и решения","track":"Политика","topic":"Институты и решения","duration":"10 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «political accountability».","options":["конституционные права","реализация государственной политики","политическая подотчётность","прозрачность институтов"],"correctAnswer":"политическая подотчётность","explanation":"«political accountability» — «политическая подотчётность»."},{"id":2,"question":"Какое выражение на британском английском соответствует «реализация государственной политики»?","options":["electoral participation","public consultation","political accountability","policy implementation"],"correctAnswer":"policy implementation","explanation":"«policy implementation» — «реализация государственной политики»."},{"id":3,"question":"Выбери точное русское значение выражения «public consultation».","options":["общественные консультации","реализация государственной политики","независимый надзор","парламентский комитет"],"correctAnswer":"общественные консультации","explanation":"«public consultation» — «общественные консультации»."},{"id":4,"question":"Выбери точное русское значение выражения «institutional transparency».","options":["прозрачность институтов","представительство меньшинств","медиаграмотность","независимый надзор"],"correctAnswer":"прозрачность институтов","explanation":"«institutional transparency» — «прозрачность институтов»."},{"id":5,"question":"Какое выражение на британском английском соответствует «парламентский комитет»?","options":["constitutional rights","media literacy","parliamentary committee","