INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000223,'challenges','{"id":760300000000223,"title":"C1 · Политика · Институты и решения · Challenge 23","description":"C1: институты и решения. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"⚡","xp":46,"category":"Институты и решения","track":"Политика","topic":"Институты и решения","duration":"11 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «evidence-based deliberation».","options":["демократическая легитимность","обсуждение на основе фактических данных","толкование конституции","подотчётность государственного сектора"],"correctAnswer":"обсуждение на основе фактических данных","explanation":"«evidence-based deliberation» — «обсуждение на основе фактических данных»."},{"id":2,"question":"Какое выражение на британском английском соответствует «процедурная справедливость»?","options":["procedural fairness","parliamentary scrutiny","civic engagement","constitutional interpretation"],"correctAnswer":"procedural fairness","explanation":"«procedural fairness» — «процедурная справедливость»."},{"id":3,"question":"Выбери точное русское значение выражения «parliamentary scrutiny».","options":["оценка государственной политики","процедурная справедливость","парламентский контроль","делиберативная демократия"],"correctAnswer":"парламентский контроль","explanation":"«parliamentary scrutiny» — «парламентский контроль»."},{"id":4,"question":"Выбери точное русское значение выражения «constitutional interpretation».","options":["институциональные гарантии","подотчётность государственного сектора","толкование конституции","парламентский контроль"],"correctAnswer":"толкование конституции","explanation":"«constitutional interpretation» — «толкование конституции»."},{"id":5,"question":"Какое выражение на британском английском соответствует «демократическая легитимность»?","options":["evidence-based deliberation","judicial independence","deliberative democracy","democratic legitimacy"],"correctAnswer":"democratic legitimacy","explanation":"«democratic legitimacy» — «демократическая легитимность»."},{"id":6,"question":"Выбери точное русское значение выражения «civic engagement».","options":["гражданская вовлечённость","процедурная справедливость","делиберативная демократия","обсуждение на основе фактических данных"],"correctAnswer":"гражданская вовлечённость","explanation":"«civic engagement» — «гражданская вовлечённость»."},{"id":7,"question":"Выбери точное русское значение выражения «deliberative democracy».","options":["толкование конституции","обсуждение на основе фактических данных","делиберативная демократия","подотчётность государственного сектора"],"correctAnswer":"делиберативная демократия","explanation":"«deliberative democracy» — «делиберативная демократия»."},{"id":8,"question":"Какое выражение на британском английском соответствует «институциональные гарантии»?","options":["institutional safeguards","deliberative democracy","parliamentary scrutiny","procedural fairness"],"correctAnswer":"institutional safeguards","explanation":"«institutional safeguards» — «институциональные гарантии»."}],"durationMinutes":11,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 46 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000224,'challenges','{"id":760300000000224,"title":"C2 · Политика · Институты и решения · Challenge 24","description":"C2: институты и решения. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"⚡","xp":51,"category":"Институты и решения","track":"Политика","topic":"Институты и решения","duration":"12 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «distinguish correlation from causation».","options":["отличить корреляцию от причинности","сбалансировать прозрачность и конфиденциальность","избегать партийно-пристрастной подачи","согласовать конкурирующие общественные интересы"],"correctAnswer":"отличить корреляцию от причинности","explanation":"«distinguish correlation from causation» — «отличить корреляцию от причинности»."},{"id":2,"question":"Какое выражение на британском английском соответствует «изучить процессуальные гарантии»?","options":["examine procedural safeguards","evaluate institutional legitimacy","distinguish correlation from causation","scrutinise constitutional constraints"],"correctAnswer":"examine procedural safeguards","explanation":"«examine procedural safeguards» — «изучить процессуальные гарантии»."},{"id":3,"question":"Выбери точное русское значение выражения «challenge an unsubstantiated claim».","options":["сформулировать проверку соразмерности","избегать партийно-пристрастной подачи","оспорить неподкреплённое утверждение","обеспечить беспристрастность суда"],"correctAnswer":"оспорить неподкреплённое утверждение","explanation":"«challenge an unsubstantiated claim» — «оспорить неподкреплённое утверждение»."},{"id":4,"question":"Выбери точное русское значение выражения «scrutinise constitutional constraints».","options":["тщательно изучить конституционные ограничения","согласовать конкурирующие общественные интересы","оценить устойчивость демократии","проанализировать захват регулятора"],"correctAnswer":"тщательно изучить конституционные ограничения","explanation":"«scrutinise constitutional constraints» — «тщательно изучить конституционные ограничения»."},{"id":5,"question":"Какое выражение на британском английском соответствует «согласовать конкурирующие общественные интересы»?","options":["scrutinise constitutional constraints","safeguard judicial impartiality","evaluate institutional legitimacy","reconcile competing public interests"],"correctAnswer":"reconcile competing public interests","explanation":"«reconcile competing public interests» — «согласовать конкурирующие общественные интересы»."},{"id":6,"question":"Выбери точное русское значение выражения «articulate a proportionality test».","options":["сформулировать проверку соразмерности","проанализировать захват регулятора","отличить корреляцию от причинности","избегать партийно-пристрастной подачи"],"correctAnswer":"сформулировать проверку соразмерности","explanation":"«articulate a proportionality test» — «сформулировать проверку соразмерности»."},{"id":7,"question":"Выбери точное русское значение выражения «evaluate institutional legitimacy».","options":["оценить легитимность института","изучить процессуальные гарантии","проанализировать захват регулятора","сформулировать проверку соразмерности"],"correctAnswer":"оценить легитимность института","explanation":"«evaluate institutional legitimacy» — «оценить легитимность института»."},{"id":8,"question":"Какое выражение на британском английском соответствует «сбалансировать прозрачность и конфиденциальность»?","options":["scrutinise constitutional constraints","balance transparency and privacy","safeguard judicial impartiality","analyse regulatory capture"],"correctAnswer":"balance transparency and privacy","explanation":"«balance transparency and privacy» — «сбалансировать прозрачность и конфиденциальность»."}],"durationMinutes":12,"goal":"Ответь на 8 вопросов и сравни результат.","instructions"