INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000226,'challenges','{"id":760300000000226,"title":"A2 · Политика · Аргументы и источники · Challenge 26","description":"A2: аргументы и источники. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"⚡","xp":34,"category":"Аргументы и источники","track":"Политика","topic":"Аргументы и источники","duration":"8 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «citizens'' rights».","options":["собрание сообщества","права граждан","общественная библиотека","школьный совет"],"correctAnswer":"права граждан","explanation":"«citizens'' rights» — «права граждан»."},{"id":2,"question":"Какое выражение на британском английском соответствует «местный совет»?","options":["elect a leader","community meeting","local council","school council"],"correctAnswer":"local council","explanation":"«local council» — «местный совет»."},{"id":3,"question":"Выбери точное русское значение выражения «community meeting».","options":["школьный совет","соблюдать правило","местный совет","собрание сообщества"],"correctAnswer":"собрание сообщества","explanation":"«community meeting» — «собрание сообщества»."},{"id":4,"question":"Выбери точное русское значение выражения «follow a rule».","options":["государственная услуга","соблюдать правило","права граждан","местный совет"],"correctAnswer":"соблюдать правило","explanation":"«follow a rule» — «соблюдать правило»."},{"id":5,"question":"Какое выражение на британском английском соответствует «поделиться мнением»?","options":["public service","school council","share an opinion","equal treatment"],"correctAnswer":"share an opinion","explanation":"«share an opinion» — «поделиться мнением»."},{"id":6,"question":"Выбери точное русское значение выражения «public discussion».","options":["государственная услуга","равное обращение","поделиться мнением","общественная дискуссия"],"correctAnswer":"общественная дискуссия","explanation":"«public discussion» — «общественная дискуссия»."},{"id":7,"question":"Выбери точное русское значение выражения «elect a leader».","options":["собрание сообщества","соблюдать правило","избрать лидера","местный совет"],"correctAnswer":"избрать лидера","explanation":"«elect a leader» — «избрать лидера»."},{"id":8,"question":"Какое выражение на британском английском соответствует «государственная услуга»?","options":["citizens'' rights","share an opinion","public service","public library"],"correctAnswer":"public service","explanation":"«public service» — «государственная услуга»."}],"durationMinutes":8,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 34 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000227,'challenges','{"id":760300000000227,"title":"B1 · Политика · Аргументы и источники · Challenge 27","description":"B1: аргументы и источники. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"⚡","xp":36,"category":"Аргументы и источники","track":"Политика","topic":"Аргументы и источники","duration":"9 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «voting system».","options":["местные выборы","система голосования","общественные дебаты","мирное выражение несогласия"],"correctAnswer":"система голосования","explanation":"«voting system» — «система голосования»."},{"id":2,"question":"Какое выражение на британском английском соответствует «гражданское участие»?","options":["civic participation","public interest","voting system","local election"],"correctAnswer":"civic participation","explanation":"«civic participation» — «гражданское участие»."},{"id":3,"question":"Выбери точное русское значение выражения «peaceful disagreement».","options":["местные выборы","мирное выражение несогласия","общественная ответственность","государственное финансирование"],"correctAnswer":"мирное выражение несогласия","explanation":"«peaceful disagreement» — «мирное выражение несогласия»."},{"id":4,"question":"Выбери точное русское значение выражения «independent journalism».","options":["мирное выражение несогласия","общественная ответственность","независимая журналистика","надёжный источник"],"correctAnswer":"независимая журналистика","explanation":"«independent journalism» — «независимая журналистика»."},{"id":5,"question":"Какое выражение на британском английском соответствует «государственное финансирование»?","options":["voting system","social responsibility","civic participation","government funding"],"correctAnswer":"government funding","explanation":"«government funding» — «государственное финансирование»."},{"id":6,"question":"Выбери точное русское значение выражения «local election».","options":["государственное финансирование","местные выборы","общественные дебаты","общественный интерес"],"correctAnswer":"местные выборы","explanation":"«local election» — «местные выборы»."},{"id":7,"question":"Выбери точное русское значение выражения «public policy».","options":["независимая журналистика","надёжный источник","общественные дебаты","государственная политика"],"correctAnswer":"государственная политика","explanation":"«public policy» — «государственная политика»."},{"id":8,"question":"Какое выражение на британском английском соответствует «представительная демократия»?","options":["civic participation","social responsibility","representative democracy","public interest"],"correctAnswer":"representative democracy","explanation":"«representative democracy» — «представительная демократия»."}],"durationMinutes":9,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 36 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000228,'challenges','{"id":760300000000228,"title":"B2 · Политика · Аргументы и источники · Challenge 28","description":"B2: аргументы и источники. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"⚡","xp":41,"category":"Аргументы и источники","track":"Политика","topic":"Аргументы и источники","duration":"10 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «public consultation».","options":["политика на основе фактических данных","участие в выборах","общественные консультации","прозрачность институтов"],"correctAnswer":"общественные консультации","explanation":"«public consultation» — «общественные консультации»."},{"id":2,"question":"Какое выражение на британском английском соответствует «независимый надзор»?","options":["policy implementation","electoral participation","independent oversight","institutional transparency"],"correctAnswer":"independent oversight","explanation":"«independent oversight» — «независимый надзор»."},{"id":3,"question":"Выбери точное русское значение выражения «evidence-based policy».","options":["политика на основе фактических данных","парламентский комитет","законодательное предложение","независимый надзор"],"correctAnswer":"политика на основе фактических данных","explanation":"«evidence-based policy» — «политика на основе фактических данных»."},{"id":4,"question":"Выбери точное русское значение выражения «electoral participation».","options":["участие в выборах","общественные консультации","политика на основе фактических данных","реализация государственной политики"],"correctAnswer":"участие в выборах","explanation":"«electoral participation» — «участие в выборах»."},{"id":5,"question":"Какое выражение на британском английском соответствует «прозрачность институтов»?","options":["public consultation","policy implementation","media literacy","institutional transparency"],"correctAnswer":"institutional transparency","explanation":"«institutional transparency» — «прозрачность институтов»."},{"id":6,"question":"Выбери точное русское значение выражения «policy implementation».","options":["политика на основе фактических данных","независимый надзор","общественные консультации","реализация государственной политики"],"correctAnswer":"реализация государственной политики","explanation":"«policy implementation» — «реализация государственной политики»."},{"id":7,"question":"Выбери точное русское значение выражения «political accountability».","options":["медиаграмотность","прозрачность институтов","политическая подотчётность","представительство меньшинств"],"correctAnswer":"политическая подотчётность","explanation":"«political accountability» — «политическая подотчётность»."},{"id":8,"question":"Какое выражение на британском английском соответствует «законодательное предложение»?","options":["media literacy","public consultation","parliamentary committee","legislative proposal"],"correctAnswer":"legislative proposal","explanation":"«legislative proposal» — «законодательное предложение»."}],"durationMinutes":10,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 41 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000229,'challenges','{"id":760300000000229,"title":"C1 · Политика · Аргументы и источники · Challenge 29","description":"C1: аргументы и источники. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"⚡","xp":46,"category":"Аргументы и источники","track":"Политика","topic":"Аргументы и источники","duration":"11 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «parliamentary scrutiny».","options":["делиберативная демократия","гражданская вовлечённость","независимость судебной власти","парламентский контроль"],"correctAnswer":"парламентский контроль","explanation":"«parliamentary scrutiny» — «парламентский контроль»."},{"id":2,"question":"Какое выражение на британском английском соответствует «конфликт интересов»?","options":["conflict of interest","evidence-based deliberation","deliberative democracy","democratic legitimacy"],"correctAnswer":"conflict of interest","explanation":"«conflict of interest» — «конфликт интересов»."},{"id":3,"question":"Выбери точное русское значение выражения «civic engagement».","options":["процедурная справедливость","гражданская вовлечённость","демократическая легитимность","институциональные гарантии"],"correctAnswer":"гражданская вовлечённость","explanation":"«civic engagement» — «гражданская вовлечённость»."},{"id":4,"question":"Выбери точное русское значение выражения «constitutional interpretation».","options":["парламентский контроль","конфликт интересов","толкование конституции","делиберативная демократия"],"correctAnswer":"толкование конституции","explanation":"«constitutional interpretation» — «толкование конституции»."},{"id":5,"question":"Какое выражение на британском английском соответствует «подотчётность государственного сектора»?","options":["constitutional interpretation","public-sector accountability","democratic legitimacy","procedural fairness"],"correctAnswer":"public-sector accountability","explanation":"«public-sector accountability» — «подотчётность государственного сектора»."},{"id":6,"question":"Выбери точное русское значение выражения «judicial independence».","options":["независимость судебной власти","демократическая легитимность","обсуждение на основе фактических данных","процедурная справедливость"],"correctAnswer":"независимость судебной власти","explanation":"«judicial independence» — «независимость судебной власти»."},{"id":7,"question":"Выбери точное русское значение выражения «institutional safeguards».","options":["подотчётность государственного сектора","конфликт интересов","институциональные гарантии","оценка государственной политики"],"correctAnswer":"институциональные гарантии","explanation":"«institutional safeguards» — «институциональные гарантии»."},{"id":8,"question":"Какое выражение на британском английском соответствует «делиберативная демократия»?","options":["deliberative democracy","judicial independence","conflict of interest","institutional safeguards"],"correctAnswer":"deliberative democracy","explanation":"«deliberative democracy» — «делиберативная демократия»."}],"durationMinutes":11,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 46 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000230,'challenges','{"id":760300000000230,"title":"C2 · Политика · Аргументы и источники · Challenge 30","description":"C2: аргументы и источники. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"⚡","xp":51,"category":"Аргументы и источники","track":"Политика","topic":"Аргументы и источники","duration":"12 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «distinguish correlation from causation».","options":["согласовать конкурирующие общественные интересы","отличить корреляцию от причинности","избегать партийно-пристрастной подачи","оспорить неподкреплённое утверждение"],"correctAnswer":"отличить корреляцию от причинности","explanation":"«distinguish correlation from causation» — «отличить корреляцию от причинности»."},{"id":2,"question":"Какое выражение на британском английском соответствует «сбалансировать прозрачность и конфиденциальность»?","options":["evaluate institutional legitimacy","balance transparency and privacy","challenge an unsubstantiated claim","articulate a proportionality test"],"correctAnswer":"balance transparency and privacy","explanation":"«balance transparency and privacy» — «сбалансировать прозрачность и конфиденциальность»."},{"id":3,"question":"Выбери точное русское значение выражения «evaluate institutional legitimacy».","options":["тщательно изучить конституционные ограничения","обеспечить беспристрастность суда","отличить корреляцию от причинности","оценить легитимность института"],"correctAnswer":"оценить легитимность института","explanation":"«evaluate institutional legitimacy» — «оценить легитимность института»."},{"id":4,"question":"Выбери точное русское значение выражения «safeguard judicial impartiality».","options":["обеспечить беспристрастность суда","тщательно изучить конституционные ограничения","сбалансировать прозрачность и конфиденциальность","согласовать конкурирующие общественные интересы"],"correctAnswer":"обеспечить беспристрастность суда","explanation":"«safeguard judicial impartiality» — «обеспечить беспристрастность суда»."},{"id":5,"question":"Какое выражение на британском английском соответствует «согласовать конкурирующие общественные интересы»?","options":["examine procedural safeguards","avoid partisan framing","evaluate institutional legitimacy","reconcile competing public interests"],"correctAnswer":"reconcile competing public interests","explanation":"«reconcile competing public interests» — «согласовать конкурирующие общественные интересы»."},{"id":6,"question":"Выбери точное русское значение выражения «scrutinise constitutional constraints».","options":["согласовать конкурирующие общественные интересы","сформулировать проверку соразмерности","тщательно изучить конституционные ограничения","проанализировать захват регулятора"],"correctAnswer":"тщательно изучить конституционные ограничения","explanation":"«scrutinise constitutional constraints» — «тщательно изучить конституционные ограничения»."},{"id":7,"question":"Выбери точное русское значение выражения «articulate a proportionality test».","options":["оценить легитимность института","обеспечить беспристрастность суда","сформулировать проверку соразмерности","оценить устойчивость демократии"],"correctAnswer":"сформулировать проверку соразмерности","explanation":"«articulate a proportionality test» — «сформулировать проверку соразмерности»."},{"id":8,"question":"Какое выражение на британском английском соответствует «проанализировать захват регулятора»?","options":["scrutinise constitutional constraints","analyse regulatory capture","distinguish correlation from causation","articulate a proportionality test"],"correctAnswer":"analyse regulatory capture","explanation":"«analyse regulatory capture» — «проанализировать захват регулятора»."}],"durationMinutes":12,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 51 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
