INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000232,'challenges','{"id":760300000000232,"title":"A2 · Политика · Общество и правила · Challenge 32","description":"A2: общество и правила. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"⚡","xp":31,"category":"Общество и правила","track":"Политика","topic":"Общество и правила","duration":"8 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «local council».","options":["соблюдать правило","равное обращение","государственная услуга","местный совет"],"correctAnswer":"местный совет","explanation":"«local council» — «местный совет»."},{"id":2,"question":"Какое выражение на британском английском соответствует «собрание сообщества»?","options":["elect a leader","make a decision","community meeting","equal treatment"],"correctAnswer":"community meeting","explanation":"«community meeting» — «собрание сообщества»."},{"id":3,"question":"Выбери точное русское значение выражения «school council».","options":["школьный совет","соблюдать правило","собрание сообщества","принять решение"],"correctAnswer":"школьный совет","explanation":"«school council» — «школьный совет»."},{"id":4,"question":"Выбери точное русское значение выражения «public service».","options":["соблюдать правило","государственная услуга","собрание сообщества","принять решение"],"correctAnswer":"государственная услуга","explanation":"«public service» — «государственная услуга»."},{"id":5,"question":"Какое выражение на британском английском соответствует «принять решение»?","options":["follow a rule","local council","make a decision","share an opinion"],"correctAnswer":"make a decision","explanation":"«make a decision» — «принять решение»."},{"id":6,"question":"Выбери точное русское значение выражения «public discussion».","options":["соблюдать правило","общественная дискуссия","избрать лидера","собрание сообщества"],"correctAnswer":"общественная дискуссия","explanation":"«public discussion» — «общественная дискуссия»."},{"id":7,"question":"Выбери точное русское значение выражения «equal treatment».","options":["равное обращение","собрание сообщества","общественная библиотека","местный совет"],"correctAnswer":"равное обращение","explanation":"«equal treatment» — «равное обращение»."},{"id":8,"question":"Какое выражение на британском английском соответствует «избрать лидера»?","options":["equal treatment","local council","follow a rule","elect a leader"],"correctAnswer":"elect a leader","explanation":"«elect a leader» — «избрать лидера»."}],"durationMinutes":8,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 31 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000233,'challenges','{"id":760300000000233,"title":"B1 · Политика · Общество и правила · Challenge 33","description":"B1: общество и правила. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"⚡","xp":36,"category":"Общество и правила","track":"Политика","topic":"Общество и правила","duration":"9 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «public interest».","options":["мирное выражение несогласия","общественный интерес","общественная ответственность","общественные дебаты"],"correctAnswer":"общественный интерес","explanation":"«public interest» — «общественный интерес»."},{"id":2,"question":"Какое выражение на британском английском соответствует «общественная ответственность»?","options":["local election","peaceful disagreement","public interest","social responsibility"],"correctAnswer":"social responsibility","explanation":"«social responsibility» — «общественная ответственность»."},{"id":3,"question":"Выбери точное русское значение выражения «peaceful disagreement».","options":["система голосования","мирное выражение несогласия","общественные дебаты","представительная демократия"],"correctAnswer":"мирное выражение несогласия","explanation":"«peaceful disagreement» — «мирное выражение несогласия»."},{"id":4,"question":"Выбери точное русское значение выражения «representative democracy».","options":["система голосования","общественные дебаты","представительная демократия","местные выборы"],"correctAnswer":"представительная демократия","explanation":"«representative democracy» — «представительная демократия»."},{"id":5,"question":"Какое выражение на британском английском соответствует «государственная политика»?","options":["social responsibility","public policy","voting system","independent journalism"],"correctAnswer":"public policy","explanation":"«public policy» — «государственная политика»."},{"id":6,"question":"Выбери точное русское значение выражения «civic participation».","options":["гражданское участие","общественные дебаты","государственная политика","местные выборы"],"correctAnswer":"гражданское участие","explanation":"«civic participation» — «гражданское участие»."},{"id":7,"question":"Выбери точное русское значение выражения «public debate».","options":["общественные дебаты","государственное финансирование","общественная ответственность","мирное выражение несогласия"],"correctAnswer":"общественные дебаты","explanation":"«public debate» — «общественные дебаты»."},{"id":8,"question":"Какое выражение на британском английском соответствует «государственное финансирование»?","options":["voting system","representative democracy","government funding","peaceful disagreement"],"correctAnswer":"government funding","explanation":"«government funding» — «государственное финансирование»."}],"durationMinutes":9,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 36 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000234,'challenges','{"id":760300000000234,"title":"B2 · Политика · Общество и правила · Challenge 34","description":"B2: общество и правила. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"⚡","xp":41,"category":"Общество и правила","track":"Политика","topic":"Общество и правила","duration":"10 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «public consultation».","options":["общественные консультации","независимый надзор","политическая подотчётность","законодательное предложение"],"correctAnswer":"общественные консультации","explanation":"«public consultation» — «общественные консультации»."},{"id":2,"question":"Какое выражение на британском английском соответствует «медиаграмотность»?","options":["media literacy","minority representation","independent oversight","electoral participation"],"correctAnswer":"media literacy","explanation":"«media literacy» — «медиаграмотность»."},{"id":3,"question":"Выбери точное русское значение выражения «legislative proposal».","options":["медиаграмотность","политическая подотчётность","законодательное предложение","прозрачность институтов"],"correctAnswer":"законодательное предложение","explanation":"«legislative proposal» — «законодательное предложение»."},{"id":4,"question":"Выбери точное русское значение выражения «policy implementation».","options":["реализация государственной политики","политическая подотчётность","парламентский комитет","прозрачность институтов"],"correctAnswer":"реализация государственной политики","explanation":"«policy implementation» — «реализация государственной политики»."},{"id":5,"question":"Какое выражение на британском английском соответствует «представительство меньшинств»?","options":["institutional transparency","independent oversight","minority representation","parliamentary committee"],"corr