INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000235,'challenges','{"id":760300000000235,"title":"C1 · Политика · Общество и правила · Challenge 35","description":"C1: общество и правила. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"⚡","xp":46,"category":"Общество и правила","track":"Политика","topic":"Общество и правила","duration":"11 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «public-sector accountability».","options":["конфликт интересов","институциональные гарантии","демократическая легитимность","подотчётность государственного сектора"],"correctAnswer":"подотчётность государственного сектора","explanation":"«public-sector accountability» — «подотчётность государственного сектора»."},{"id":2,"question":"Какое выражение на британском английском соответствует «институциональные гарантии»?","options":["conflict of interest","parliamentary scrutiny","deliberative democracy","institutional safeguards"],"correctAnswer":"institutional safeguards","explanation":"«institutional safeguards» — «институциональные гарантии»."},{"id":3,"question":"Выбери точное русское значение выражения «constitutional interpretation».","options":["гражданская вовлечённость","делиберативная демократия","институциональные гарантии","толкование конституции"],"correctAnswer":"толкование конституции","explanation":"«constitutional interpretation» — «толкование конституции»."},{"id":4,"question":"Выбери точное русское значение выражения «civic engagement».","options":["гражданская вовлечённость","толкование конституции","обсуждение на основе фактических данных","оценка государственной политики"],"correctAnswer":"гражданская вовлечённость","explanation":"«civic engagement» — «гражданская вовлечённость»."},{"id":5,"question":"Какое выражение на британском английском соответствует «процедурная справедливость»?","options":["judicial in