INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000236,'challenges','{"id":760300000000236,"title":"C2 · Политика · Общество и правила · Challenge 36","description":"C2: общество и правила. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"⚡","xp":54,"category":"Общество и правила","track":"Политика","topic":"Общество и правила","duration":"12 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «distinguish correlation from causation».","options":["тщательно изучить конституционные ограничения","отличить корреляцию от причинности","сформулировать проверку соразмерности","оценить устойчивость демократии"],"correctAnswer":"отличить корреляцию от причинности","explanation":"«distinguish correlation from causation» — «отличить корреляцию от причинности»."},{"id":2,"question":"Какое выражение на британском английском соответствует «проанализировать захват регулятора»?","options":["challenge an unsubstantiated claim","safeguard judicial impartiality","analyse regulatory capture","assess democratic resilience"],"correctAnswer":"analyse regulatory capture","explanation":"«analyse regulatory capture» — «проанализировать захват регулятора»."},{"id":3,"question":"Выбери точное русское значение выражения «balance transparency and privacy».","options":["обеспечить беспристрастность суда","сбалансировать прозрачность и конфиденциальность","согласовать конкурирующие общественные интересы","тщательно изучить конституционные ограничения"],"correctAnswer":"сбалансировать прозрачность и конфиденциальность","explanation":"«balance transparency and privacy» — «сбалансировать прозрачность и конфиденциальность»."},{"id":4,"question":"Выбери точное русское значение выражения «scrutinise constitutional constraints».","options":["сформулировать проверку соразмерности","проанализировать захват регулятора","тщательно изучить конституционные ограничения","обеспечить беспристрастность суда"],"correctAnswer":"тщательно изучить конституционные ограничения","explanation":"«scrutinise constitutional constraints» — «тщательно изучить конституционные ограничения»."},{"id":5,"question":"Какое выражение на британском английском соответствует «оспорить неподкреплённое утверждение»?","options":["balance transparency and privacy","examine procedural safeguards","challenge an unsubstantiated claim","avoid partisan framing"],"correctAnswer":"challenge an unsubstantiated claim","explanation":"«challenge an unsubstantiated claim» — «оспорить неподкреплённое утверждение»."},{"id":6,"question":"Выбери точное русское значение выражения «evaluate institutional legitimacy».","options":["отличить корреляцию от причинности","оценить легитимность института","изучить процессуальные гарантии","тщательно изучить конституционные ограничения"],"correctAnswer":"оценить легитимность института","explanation":"«evaluate institutional legitimacy» — «оценить легитимность института»."},{"id":7,"question":"Выбери точное русское значение выражения «reconcile competing public interests».","options":["сбалансировать прозрачность и конфиденциальность","согласовать конкурирующие общественные интересы","избегать партийно-пристрастной подачи","тщательно изучить конституционные ограничения"],"correctAnswer":"согласовать конкурирующие общественные интересы","explanation":"«reconcile competing public interests» — «согласовать конкурирующие общественные интересы»."},{"id":8,"question":"Какое выражение на британском английском соответствует «избегать партийно-пристрастной подачи»?","options":["avoid partisan framing","reconcile competing public interests","scrutinise constitutional constraints","analyse regulatory capture"],"correctAnswer":"avoid partisan framing","explanation":"«avoid partisan framing» — «избегать партийно-пристрастной подачи»."}],"durationMinutes":12,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 54 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
