INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000241,'challenges','{"id":760300000000241,"title":"C1 · Политика · Гражданская жизнь · Challenge 41","description":"C1: гражданская жизнь. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"⚡","xp":49,"category":"Гражданская жизнь","track":"Политика","topic":"Гражданская жизнь","duration":"11 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «democratic legitimacy».","options":["обсуждение на основе фактических данных","гражданская вовлечённость","толкование конституции","демократическая легитимность"],"correctAnswer":"демократическая легитимность","explanation":"«democratic legitimacy» — «демократическая легитимность»."},{"id":2,"question":"Какое выражение на британском английском соответствует «независимость судебной власти»?","options":["judicial independence","institutional safeguards","conflict of interest","democratic legitimacy"],"correctAnswer":"judicial independence","explanation":"«judicial independence» — «независимость судебной власти»."},{"id":3,"question":"Выбери точное русское значение выражения «constitutional interpretation».","options":["демократическая легитимность","толкование конституции","процедурная справедливость","обсуждение на основе фактических данных"],"correctAnswer":"толкование конституции","explanation":"«constitutional interpretation» — «толкование конституции»."},{"id":4,"question":"Выбери точное русское значение выражения «evidence-based deliberation».","options":["обсуждение на основе фактических данных","демократическая легитимность","делиберативная демократия","толкование конституции"],"correctAnswer":"обсуждение на основе фактических данных","explanation":"«evidence-based deliberation» — «обсуждение на основе фактических данных»."},{"id":5,"question":"Какое выражение на британском английском соответствует «гражданская вовлечённость