INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000244,'challenges','{"id":760300000000244,"title":"A2 · Политика · Общественные обсуждения · Challenge 44","description":"A2: общественные обсуждения. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"⚡","xp":31,"category":"Общественные обсуждения","track":"Политика","topic":"Общественные обсуждения","duration":"8 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «public service».","options":["государственная услуга","поделиться мнением","принять решение","соблюдать правило"],"correctAnswer":"государственная услуга","explanation":"«public service» — «государственная услуга»."},{"id":2,"question":"Какое выражение на британском английском соответствует «принять решение»?","options":["local council","share an opinion","make a decision","public service"],"correctAnswer":"make a decision","explanation":"«make a decision» — «принять решение»."},{"id":3,"question":"Выбери точное русское значение выражения «school council».","options":["избрать лидера","равное обращение","общественная дискуссия","школьный совет"],"correctAnswer":"школьный совет","explanation":"«school council» — «школьный совет»."},{"id":4,"question":"Выбери точное русское значение выражения «public discussion».","options":["государственная услуга","общественная дискуссия","поделиться мнением","равное обращение"],"correctAnswer":"общественная дискуссия","explanation":"«public discussion» — «общественная дискуссия»."},{"id":5,"question":"Какое выражение на британском английском соответствует «собрание сообщества»?","options":["public service","make a decision","community meeting","equal treatment"],"correctAnswer":"community meeting","explanation":"«community meeting» — «собрание сообщества»."},{"id":6,"question":"Выбери точное русское значение выражения «citizens'' rights».","options":["соблюдать правило","общественная библиотека","школьный совет","права граждан"],"correctAnswer":"права граждан","explanation":"«citizens'' rights» — «права граждан»."},{"id":7,"question":"Выбери точное русское значение выражения «public library».","options":["избрать лидера","общественная библиотека","общественная дискуссия","равное обращение"],"correctAnswer":"общественная библиотека","explanation":"«public library» — «общественная библиотека»."},{"id":8,"question":"Какое выражение на британском английском соответствует «соблюдать правило»?","options":["make a decision","public library","follow a rule","citizens'' rights"],"correctAnswer":"follow a rule","explanation":"«follow a rule» — «соблюдать правило»."}],"durationMinutes":8,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 31 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000245,'challenges','{"id":760300000000245,"title":"B1 · Политика · Общественные обсуждения · Challenge 45","description":"B1: общественные обсуждения. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"⚡","xp":36,"category":"Общественные обсуждения","track":"Политика","topic":"Общественные обсуждения","duration":"9 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «social responsibility».","options":["гражданское участие","представительная демократия","общественная ответственность","общественный интерес"],"correctAnswer":"общественная ответственность","explanation":"«social responsibility» — «общественная ответственность»."},{"id":2,"question":"Какое выражение на британском английском соответствует «система голосования»?","options":["social responsibility","voting system","reliable source","local election"],"correctAnswer":"voting system","explanation":"«voting system» — «система голосования»."},{"id":3,"question":"Выбери точное русское значение выражения «public debate».","options":["система голосования","независимая журналистика","мирное выражение несогласия","общественные дебаты"],"correctAnswer":"общественные дебаты","explanation":"«public debate» — «общественные дебаты»."},{"id":4,"question":"Выбери точное русское значение выражения «civic participation».","options":["общественный интерес","государственное финансирование","надёжный источник","гражданское участие"],"correctAnswer":"гражданское участие","explanation":"«civic participation» — «гражданское участие»."},{"id":5,"question":"Какое выражение на британском английском соответствует «государственная политика»?","options":["representative democracy","public policy","independent journalism","government funding"],"correctAnswer":"public policy","explanation":"«public policy» — «государственная политика»."},{"id":6,"question":"Выбери точное русское значение выражения «peaceful disagreement».","options":["мирное выражение несогласия","система голосования","независимая журналистика","надёжный источник"],"correctAnswer":"мирное выражение несогласия","explanation":"«peaceful disagreement» — «мирное выражение несогласия»."},{"id":7,"question":"Выбери точное русское значение выражения «representative democracy».","options":["общественный интерес","независимая журналистика","гражданское участие","представительная демократия"],"correctAnswer":"представительная демократия","explanation":"«representative democracy» — «представительная демократия»."},{"id":8,"question":"Какое выражение на британском английском соответствует «независимая журналистика»?","options":["local election","social responsibility","voting system","independent journalism"],"correctAnswer":"independent journalism","explanation":"«independent journalism» — «независимая журналистика»."}],"durationMinutes":9,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 36 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000246,'challenges','{"id":760300000000246,"title":"B2 · Политика · Общественные обсуждения · Challenge 46","description":"B2: общественные обсуждения. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"⚡","xp":44,"category":"Общественные обсуждения","track":"Политика","topic":"Общественные обсуждения","duration":"10 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «parliamentary committee».","options":["парламентский комитет","конституционные права","представительство меньшинств","законодательное предложение"],"correctAnswer":"парламентский комитет","explanation":"«parliamentary committee» — «парламентский комитет»."},{"id":2,"question":"Какое выражение на британском английском соответствует «медиаграмотность»?","options":["media literacy","constitutional rights","institutional transparency","evidence-based policy"],"correctAnswer":"media literacy","explanation":"«media literacy» — «медиаграмотность»."},{"id":3,"question":"Выбери точное русское значение выражения «political accountability».","options":["парламентский комитет","политическая подотчётность","представительство меньшинств","медиаграмотность"],"correctAnswer":"политическая подотчётность","explanation":"«political accountability» — «политическая подотчётность»."},{"id":4,"question":"Выбери точное русское значение выражения «evidence-based policy».","options":["общественные консультации","политика на основе фактических данных","медиаграмотность","реализация государственной политики"],"correctAnswer":"политика на основе фактических данных","explanation":"«evidence-based policy» — «политика на основе фактических данных»."},{"id":5,"question":"Какое выражение на британском английском соответствует «конституционные права»?","options":["constitutional rights","evidence-based policy","political accountability","legislative proposal"],"correctAnswer":"constitutional rights","explanation":"«constitutional rights» — «конституционные права»."},{"id":6,"question":"Выбери точное русское значение выражения «legislative proposal».","options":["парламентский комитет","законодательное предложение","медиаграмотность","политическая подотчётность"],"correctAnswer":"законодательное предложение","explanation":"«legislative proposal» — «законодательное предложение»."},{"id":7,"question":"Выбери точное русское значение выражения «policy implementation».","options":["реализация государственной политики","конституционные права","политическая подотчётность","участие в выборах"],"correctAnswer":"реализация государственной политики","explanation":"«policy implementation» — «реализация государственной политики»."},{"id":8,"question":"Какое выражение на британском английском соответствует «участие в выборах»?","options":["minority representation","institutional transparency","legislative proposal","electoral participation"],"correctAnswer":"electoral participation","explanation":"«electoral participation» — «участие в выборах»."}],"durationMinutes":10,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 44 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000247,'challenges','{"id":760300000000247,"title":"C1 · Политика · Общественные обсуждения · Challenge 47","description":"C1: общественные обсуждения. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"⚡","xp":46,"category":"Общественные обсуждения","track":"Политика","topic":"Общественные обсуждения","duration":"11 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «public-sector accountability».","options":["подотчётность государственного сектора","демократическая легитимность","институциональные гарантии","гражданская вовлечённость"],"correctAnswer":"подотчётность государственного сектора","explanation":"«public-sector accountability» — «подотчётность государственного сектора»."},{"id":2,"question":"Какое выражение на британском английском соответствует «демократическая легитимность»?","options":["public-sector accountability","democratic legitimacy","constitutional interpretation","judicial independence"],"correctAnswer":"democratic legitimacy","explanation":"«democratic legitimacy» — «демократическая легитимность»."},{"id":3,"question":"Выбери точное русское значение выражения «policy evaluation».","options":["оценка государственной политики","институциональные гарантии","процедурная справедливость","парламентский контроль"],"correctAnswer":"оценка государственной политики","explanation":"«policy evaluation» — «оценка государственной политики»."},{"id":4,"question":"Выбери точное русское значение выражения «judicial independence».","options":["подотчётность государственного сектора","обсуждение на основе фактических данных","демократическая легитимность","независимость судебной власти"],"correctAnswer":"независимость судебной власти","explanation":"«judicial independence» — «независимость судебной власти»."},{"id":5,"question":"Какое выражение на британском английском соответствует «гражданская вовлечённость»?","options":["judicial independence","procedural fairness","parliamentary scrutiny","civic engagement"],"correctAnswer":"civic engagement","explanation":"«civic engagement» — «гражданская вовлечённость»."},{"id":6,"question":"Выбери точное русское значение выражения «deliberative democracy».","options":["подотчётность государственного сектора","толкование конституции","демократическая легитимность","делиберативная демократия"],"correctAnswer":"делиберативная демократия","explanation":"«deliberative democracy» — «делиберативная демократия»."},{"id":7,"question":"Выбери точное русское значение выражения «institutional safeguards».","options":["конфликт интересов","институциональные гарантии","процедурная справедливость","обсуждение на основе фактических данных"],"correctAnswer":"институциональные гарантии","explanation":"«institutional safeguards» — «институциональные гарантии»."},{"id":8,"question":"Какое выражение на британском английском соответствует «парламентский контроль»?","options":["institutional safeguards","constitutional interpretation","parliamentary scrutiny","public-sector accountability"],"correctAnswer":"parliamentary scrutiny","explanation":"«parliamentary scrutiny» — «парламентский контроль»."}],"durationMinutes":11,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 46 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000248,'challenges','{"id":760300000000248,"title":"C2 · Политика · Общественные обсуждения · Challenge 48","description":"C2: общественные обсуждения. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"⚡","xp":51,"category":"Общественные обсуждения","track":"Политика","topic":"Общественные обсуждения","duration":"12 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «balance transparency and privacy».","options":["сбалансировать прозрачность и конфиденциальность","сформулировать проверку соразмерности","тщательно изучить конституционные ограничения","отличить корреляцию от причинности"],"correctAnswer":"сбалансировать прозрачность и конфиденциальность","explanation":"«balance transparency and privacy» — «сбалансировать прозрачность и конфиденциальность»."},{"id":2,"question":"Какое выражение на британском английском соответствует «отличить корреляцию от причинности»?","options":["distinguish correlation from causation","evaluate institutional legitimacy","balance transparency and privacy","challenge an unsubstantiated claim"],"correctAnswer":"distinguish correlation from causation","explanation":"«distinguish correlation from causation» — «отличить корреляцию от причинности»."},{"id":3,"question":"Выбери точное русское значение выражения «examine procedural safeguards».","options":["оценить устойчивость демократии","изучить процессуальные гарантии","сбалансировать прозрачность и конфиденциальность","тщательно изучить конституционные ограничения"],"correctAnswer":"изучить процессуальные гарантии","explanation":"«examine procedural safeguards» — «изучить процессуальные гарантии»."},{"id":4,"question":"Выбери точное русское значение выражения «analyse regulatory capture».","options":["обеспечить беспристрастность суда","проанализировать захват регулятора","сбалансировать прозрачность и конфиденциальность","оспорить неподкреплённое утверждение"],"correctAnswer":"проанализировать захват регулятора","explanation":"«analyse regulatory capture» — «проанализировать захват регулятора»."},{"id":5,"question":"Какое выражение на британском английском соответствует «оспорить неподкреплённое утверждение»?","options":["evaluate institutional legitimacy","balance transparency and privacy","distinguish correlation from causation","challenge an unsubstantiated claim"],"correctAnswer":"challenge an unsubstantiated claim","explanation":"«challenge an unsubstantiated claim» — «оспорить неподкреплённое утверждение»."},{"id":6,"question":"Выбери точное русское значение выражения «avoid partisan framing».","options":["сбалансировать прозрачность и конфиденциальность","избегать партийно-пристрастной подачи","оспорить неподкреплённое утверждение","сформулировать проверку соразмерности"],"correctAnswer":"избегать партийно-пристрастной подачи","explanation":"«avoid partisan framing» — «избегать партийно-пристрастной подачи»."},{"id":7,"question":"Выбери точное русское значение выражения «evaluate institutional legitimacy».","options":["согласовать конкурирующие общественные интересы","сбалансировать прозрачность и конфиденциальность","оценить легитимность института","проанализировать захват регулятора"],"correctAnswer":"оценить легитимность института","explanation":"«evaluate institutional legitimacy» — «оценить легитимность института»."},{"id":8,"question":"Какое выражение на британском английском соответствует «тщательно изучить конституционные ограничения»?","options":["evaluate institutional legitimacy","examine procedural safeguards","scrutinise constitutional constraints","distinguish correlation from causation"],"correctAnswer":"scrutinise constitutional constraints","explanation":"«scrutinise constitutional constraints» — «тщательно изучить конституционные ограничения»."}],"durationMinutes":12,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 51 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
